DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$pilot$PT108-S3-Q6$pilot$ AND q.stimulus=$pilot$Shortly after the power plant opened and began discharging its wastewater into the river, there was a decrease in the overall number of bass caught by anglers downstream from the plant.$pilot$ AND q.prompt=$pilot$Each of the following, if true, could explain the decrease described above EXCEPT:$pilot$ AND q.correct_choice=$pilot$C$pilot$) THEN RAISE EXCEPTION 'Question changed: PT108-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT108-S3-Q6$pilot$ AND c.letter=$pilot$A$pilot$ AND c.choice_text=$pilot$The discharged wastewater made the river more attractive to fish that are the natural predators of bass.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT108-S3-Q6 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT108-S3-Q6$pilot$ AND c.letter=$pilot$B$pilot$ AND c.choice_text=$pilot$The discharged water was warmer than the normal river temperature, leading the bass to seek cooler water elsewhere.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT108-S3-Q6 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT108-S3-Q6$pilot$ AND c.letter=$pilot$C$pilot$ AND c.choice_text=$pilot$Because of the new plant, access to the part of the river downstream from the plant was improved, leading to an increase in the number of anglers fishing for bass.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT108-S3-Q6 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT108-S3-Q6$pilot$ AND c.letter=$pilot$D$pilot$ AND c.choice_text=$pilot$Because of the new plant, the level of noise downstream increased, making that section of the river a less popular place for anglers to fish.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT108-S3-Q6 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT108-S3-Q6$pilot$ AND c.letter=$pilot$E$pilot$ AND c.choice_text=$pilot$The discharged wastewater created turbulence that disrupted the vegetation of the river downstream, destroying some of the bass's natural habitat.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT108-S3-Q6 E'; END IF; END $guard$;
